import { css, cx } from "@styled-system/css"
import { Slot } from "radix-ui"
import { type ComponentPropsWithoutRef, forwardRef } from "react"

import { type ChipVariantProps, recipe } from "./recipe"

export type ChipProps = ComponentPropsWithoutRef<"button"> &
  ChipVariantProps & {
    asChild?: boolean
  }

export const Chip = forwardRef<HTMLButtonElement, ChipProps>(
  ({ asChild, className, children, ...props }, ref) => {
    const Comp = asChild ? Slot.Root : "button"
    const [variantProps, componentProps] = recipe.splitVariantProps(props)
    const styles = recipe.raw(variantProps)

    return (
      <Comp
        ref={ref}
        className={cx(css(styles), className)}
        {...componentProps}
      >
        {children}
      </Comp>
    )
  },
)

Chip.displayName = "Chip"

import { cva, type RecipeVariantProps } from "@styled-system/css"

export type ChipVariantProps = RecipeVariantProps<typeof recipe>
export const recipe = cva({
  base: {
    alignItems: "center",
    borderRadius: "full",
    cursor: "pointer",
    display: "inline-flex",
    flexShrink: 0,
    justifyContent: "center",
    transition: "colors",
    whiteSpace: "nowrap",

    "& svg": {
      flexShrink: 0,
    },

    _disabled: {
      cursor: "not-allowed",
      opacity: 0.5,
    },
  },
  variants: {
    variant: {
      filled: {
        bg: "secondary",
        color: "secondary.foreground",
        "&:not(:disabled):hover": {
          bg: "secondary.active",
        },
      },
      outlined: {
        bg: "layer",
        border: "base",
        color: "foreground.emphasized",
        "&:not(:disabled):hover": {
          bg: "neutral.active",
        },
      },
    },
    size: {
      sm: {
        fontSize: "sm",
        height: "7",
        textStyle: "label2",
        "& svg": {
          height: "3",
          width: "3",
        },
      },
      md: {
        fontSize: "lg",
        height: "9",
        textStyle: "label1",
        "& svg": {
          height: "4",
          width: "4",
        },
      },
    },
    layout: {
      withText: {},
      iconOnly: {
        px: "2",
        "& svg": {
          m: "0",
        },
      },
    },
  },
  compoundVariants: [
    {
      layout: "iconOnly",
      size: "sm",
      css: {
        height: "7",
        width: "7",
      },
    },
    {
      layout: "iconOnly",
      size: "md",
      css: {
        height: "9",
        width: "9",
      },
    },
    {
      layout: "withText",
      size: "sm",
      css: {
        gap: "1",
        px: "2",
        py: "1",
      },
    },
    {
      layout: "withText",
      size: "md",
      css: {
        gap: "2",
        px: "3",
        py: "2",
      },
    },
  ],
  defaultVariants: {
    variant: "filled",
    size: "md",
    layout: "withText",
  },
})

import { cn } from "@utils/cn"
import { Slot } from "radix-ui"
import { type ComponentPropsWithoutRef, forwardRef } from "react"
import { type VariantProps } from "tailwind-variants"

import { chip } from "./styles"

export type ChipVariantProps = VariantProps<typeof chip>

export type ChipProps = ComponentPropsWithoutRef<"button"> &
  ChipVariantProps & {
    asChild?: boolean
  }

export const Chip = forwardRef<HTMLButtonElement, ChipProps>(
  (
    { asChild, className, variant, size, layout, children, ...componentProps },
    ref,
  ) => {
    const Comp = asChild ? Slot.Root : "button"

    return (
      <Comp
        ref={ref}
        className={cn(chip({ variant, size, layout }), className)}
        {...componentProps}
      >
        {children}
      </Comp>
    )
  },
)

Chip.displayName = "Chip"

import { tv } from "tailwind-variants"

export const chip = tv({
  base: [
    "inline-flex shrink-0 cursor-pointer items-center justify-center whitespace-nowrap rounded-full transition-colors",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "[&_svg]:shrink-0",
  ],
  variants: {
    variant: {
      filled:
        "bg-secondary text-secondary-foreground [&:not(:disabled):hover]:bg-secondary-active",
      outlined:
        "border border-stroke bg-layer text-foreground-emphasized [&:not(:disabled):hover]:bg-neutral-active",
    },
    size: {
      sm: "h-7 typo-label2 [&_svg]:size-3",
      md: "h-9 typo-label1 [&_svg]:size-4",
    },
    layout: {
      withText: "",
      iconOnly: "[&_svg]:m-0",
    },
  },
  compoundVariants: [
    {
      layout: "iconOnly",
      size: "sm",
      class: "size-7 px-2",
    },
    {
      layout: "iconOnly",
      size: "md",
      class: "size-9 px-2",
    },
    {
      layout: "withText",
      size: "sm",
      class: "gap-1 px-2 py-1",
    },
    {
      layout: "withText",
      size: "md",
      class: "gap-2 px-3 py-2",
    },
  ],
  defaultVariants: {
    variant: "filled",
    size: "md",
    layout: "withText",
  },
})
